// Inside createApi endpoints builder:
endpoints: (builder) => ({
  // Defining a Mutation (WRITE operation)
  addPost: builder.mutation({
    query: (newPostData) => ({
      url: '/posts',
      method: 'POST',
      body: newPostData,
    }),
  }),
})

// Inside the Component:
const [addPost, { isLoading, isError }] = useAddPostMutation();

const handleSubmit = () => {
  // Fire the mutation manually!
  addPost({ title: 'New Blog Post', content: 'Hello World' });
}
